import flax.linen as nn
import jax.numpy as jnp
from jax import random
from typing import Dict, Any

def _define_hyperparameters():
    """Define hyperparameters for the Parallel CNN-LSTM model."""
    return {
        'learning_rate': 0.001,
        'cnn_filters': 128,
        'cnn_kernel_size': 7,
        'lstm_hidden_dim': 128, # Reduced to manage parameter count
        'dropout_rate': 0.4
    }

class Parallel_CNN_LSTM(nn.Module):
    """A parallel multi-branch CNN and LSTM network."""
    d_output: int
    task_type: str
    cnn_filters: int
    cnn_kernel_size: int
    lstm_hidden_dim: int
    dropout_rate: float

    @nn.compact
    def __call__(self, x, deterministic=True):
        # Input shape: (batch, seq_len, 4)

        # --- Branch 1: CNN for local features ---
        cnn_out = nn.Conv(features=self.cnn_filters, kernel_size=(self.cnn_kernel_size,))(x)
        cnn_out = nn.relu(cnn_out)
        cnn_out = jnp.mean(cnn_out, axis=1) # Global average pooling

        # --- Branch 2: LSTM for global context ---
        lstm = nn.RNN(nn.LSTMCell(features=self.lstm_hidden_dim))
        lstm_output = lstm(x)
        lstm_out = lstm_output[:, -1, :] # Final hidden state

        # --- Concatenate branch outputs ---
        combined_features = jnp.concatenate([cnn_out, lstm_out], axis=-1)

        # --- Final prediction head ---
        out = nn.Dropout(rate=self.dropout_rate)(combined_features, deterministic=deterministic)
        out = nn.Dense(features=self.d_output)(out)

        if self.task_type == "regression":
            return out.squeeze(axis=-1)
        else:
            return out

class ParallelNetwork:
    """Wrapper for the Parallel_CNN_LSTM model."""
    def __init__(self, **kwargs):
        self.network = Parallel_CNN_LSTM(**kwargs)

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key}, dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        if deterministic:
            return self.network.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None:
                rng_key = random.PRNGKey(0)
            return self.network.apply({'params': params}, x, deterministic=False, rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    """Factory function to create the Parallel CNN-LSTM model."""
    return ParallelNetwork(
        d_output=hparams['d_output'],
        task_type=hparams['task_type'],
        cnn_filters=hparams['cnn_filters'],
        cnn_kernel_size=hparams['cnn_kernel_size'],
        lstm_hidden_dim=hparams['lstm_hidden_dim'],
        dropout_rate=hparams['dropout_rate']
    )
